CREATE TABLE s_trust_transactions(id TEXT PRIMARY KEY,request_key TEXT NOT NULL UNIQUE,account_id TEXT NOT NULL REFERENCES s_trust_accounts(id),ledger_id TEXT REFERENCES s_trust_ledgers(id),revision TEXT NOT NULL,direction TEXT NOT NULL CHECK(direction IN('receipt','disbursement')),kind TEXT NOT NULL CHECK(kind IN('receipt','retainer','check','wire','ach','cash')),cents INTEGER NOT NULL CHECK(cents>0),counterparty TEXT NOT NULL,bank_reference TEXT NOT NULL,received_date TEXT NOT NULL,effective_date TEXT NOT NULL,cleared_date TEXT,source_document_id TEXT NOT NULL REFERENCES s_documents(id),source_version INTEGER NOT NULL,source_digest TEXT NOT NULL,purpose TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE s_trust_decisions(id TEXT PRIMARY KEY,transaction_id TEXT NOT NULL UNIQUE REFERENCES s_trust_transactions(id),decision TEXT NOT NULL CHECK(decision IN('approved','declined')),actor TEXT NOT NULL,note TEXT NOT NULL,at TEXT NOT NULL);
CREATE TABLE s_trust_clearings(id TEXT PRIMARY KEY,entry_id TEXT NOT NULL UNIQUE REFERENCES s_trust_entries(id),cleared_date TEXT NOT NULL,bank_reference TEXT NOT NULL,source_document_id TEXT NOT NULL REFERENCES s_documents(id),source_version INTEGER NOT NULL,source_digest TEXT NOT NULL,actor TEXT NOT NULL,at TEXT NOT NULL);
CREATE TRIGGER s_trust_transactions_no_update BEFORE UPDATE ON s_trust_transactions BEGIN SELECT RAISE(ABORT,'trust transaction requests are immutable'); END;
CREATE TRIGGER s_trust_transactions_no_delete BEFORE DELETE ON s_trust_transactions BEGIN SELECT RAISE(ABORT,'trust transaction requests are immutable'); END;
CREATE TRIGGER s_trust_decisions_no_update BEFORE UPDATE ON s_trust_decisions BEGIN SELECT RAISE(ABORT,'trust decisions are append-only'); END;
CREATE TRIGGER s_trust_decisions_no_delete BEFORE DELETE ON s_trust_decisions BEGIN SELECT RAISE(ABORT,'trust decisions are append-only'); END;
CREATE TRIGGER s_trust_clearings_no_update BEFORE UPDATE ON s_trust_clearings BEGIN SELECT RAISE(ABORT,'trust clearance evidence is append-only'); END;
CREATE TRIGGER s_trust_clearings_no_delete BEFORE DELETE ON s_trust_clearings BEGIN SELECT RAISE(ABORT,'trust clearance evidence is append-only'); END;
